def f(p):
    s = p['S0']
    deficit = 0
    for d in range(1, p['T'] + 1):
        if d % p['a'] == 0:
            s += p['b']
        if s > p['cap']:
            s = p['cap']
        demand = p['c'] + d % p['e']
        if s >= demand:
            s -= demand
        else:
            deficit += demand - s
            s = 0
        if d % p['f'] == 0:
            s -= s // 10
    return deficit

