A2|tr2.rules:
def f(p):
    up = p['up']
    down = p['down']
    goal = p['goal']
    pos = 0
    jumps = 0
    if pos >= goal:
        return 0
    # если после пары прыжков лягушка не продвигается, а первого прыжка вперёд не хватает, цели она не достигнет
    if up - down <= 0 and up < goal:
        return -1
    forward = True
    while pos < goal:
        if forward:
            pos = pos + up
        else:
            pos = pos - down
        jumps = jumps + 1
        forward = not forward
    return jumps

